import { planFeasibility } from "./catalog-functions.mjs";

const result = await planFeasibility({
  apiKey: process.env.PLAN_JUDGE_API_KEY,
  baseUrl: process.env.PLAN_JUDGE_BASE_URL,
  model: process.env.PLAN_JUDGE_MODEL,
  problem: "编写 add(a, b)，返回两个整数的和。",
  plan: "接收两个整数，将它们相加并返回结果。",
  visibleTests: ["assert add(1, 2) == 3", "assert add(-1, 1) == 0"]
});
console.log(result.value, result.rationale);

